from collections import Counter


def transform(grid):
    # Each 3x3 noisy tile encodes one cell; ignore background colors 0 and 5.
    h, w = len(grid), len(grid[0])
    out = []
    for r0 in range(0, h, 3):
        row = []
        for c0 in range(0, w, 3):
            counts = Counter(
                grid[r][c]
                for r in range(r0, min(r0 + 3, h))
                for c in range(c0, min(c0 + 3, w))
                if grid[r][c] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
